/**
 * @param {string} name
 * @returns {string}
 */
export function greet(name) {
  return "hi " + name;
}

/**
 * @param {number} a
 * @param {number} b
 * @returns {number}
 */
export function add(a, b) {
  return a + b;
}

/**
 * @param {string} msg
 * @returns {void}
 */
export function log(msg) {
  console.log(msg);
}
